package org.deltava.acars.message;

import org.deltava.beans.flight.ScorePackage;
import org.deltava.beans.testing.CheckRide;

/**
 * A message requesting Flight Summarization. Unlike most ACARS messages, this is <i>NEVER</i> generated by the client, and is used internally by the server. 
 * @author Luke
 * @version 13.0
 * @since 13.0
 */

public class SummaryMessage extends AbstractMessage {
	
	private final ScorePackage _pkg;
	private CheckRide _cr;

	/**
	 * Creats the message.
	 * @param pkg a ScorePackage
	 */
	public SummaryMessage(ScorePackage pkg) {
		super(MessageType.SUMMARY, pkg.getPilot());
		_pkg = pkg;
	}

	/**
	 * Returns the Scoring Package.
	 * @return a ScorePackage
	 */
	public ScorePackage getPackage() {
		return _pkg;
	}
	
	/**
	 * Returns the associated Check Ride.
	 * @return a CheckRide, or null if none
	 */
	public CheckRide getCheckRide() {
		return _cr;
	}
	
	/**
	 * Sets an associated Check Ride.
	 * @param cr a CheckRide
	 */
	public void setCheckRide(CheckRide cr) {
		_cr = cr;
	}
}